	include 'all.macros'	include 'e16.locator'MMLoader	PROCTrue	equ $FFFFFalse	equ 0MyHandle	equ 0MyPointer	equ 4Ptr	equ 8TheUserID	equ $B002	phk	plb;-----------------------------------------------------------;; Get memory for use with the message center;	pha	pha	PushLong #4	PushWord #TheUserID	PushWord #0	pha	pha	_NewHandle	PullLong MyHandle;-----------------------------------------------------------;; Get the old TSPtr from the message center.;	PushWord #GetMessage	PushWord #TheUserID	PushLong MyHandle	_MessageCenter	bcs NothingThereNow	lda [MyHandle]	sta MyPointer	ldy #2	lda [MyHandle],y	sta MyPointer+2	lda >$E103C0	sta Ptr	lda >$E103C0+2	sta Ptr+2	lda [MyPointer]	ldy #8	sta [Ptr],y	ldy #2	lda [MyPointer],y	ldy #8+2	sta [Ptr],y;-----------------------------------------------------------;; Unload last patch;	pha	; space for result	PushWord #TheUserID	PushWord #0	_UserShutdown	plaNothingThereNow	lda [MyHandle]	sta MyPointer	ldy #2	lda [MyHandle],y	sta MyPointer+2	pha	pha	PushWord #0	PushWord #2	_GetTSPtr	pla	sta [MyPointer]	pla	ldy #2	sta [MyPointer],y		PushWord #AddMessage	PushWord #TheUserID	PushLong MyHandle	_MessageCenter	PushLong MyHandle	_DisposeHandle	pha	; space for dir page stack size	pha	; space for addr of	dir page stack seg	pha	; space for starting addr	pha	pha	; space for user id	PushWord #TheUserID	; user id	PushLong #TheName	; ptr to path name	PushWord #True	_InitialLoad	bcs Die	pla	; ignore userid	pla	; put starting address	sta TableAddress	pla	sta TableAddress+2	pla	; ignore dir page	pla	; ignore dir page size	lda >$C062	and #$0080	beq @NoBreak	brk 17@NoBreak	PushWord #0	; system call	PushWord #2	; install the patch	PushLong TableAddress	_SetTSPtr		_SetDefaultTPT	_Quit QuitParamsQuitParams	DC.L 0	DC.W 0TheName	str '1/MM.IN.RAM'TableAddress	DS.B 4Die		; 	pha	PushLong #ErrorString	_SysFailMgrErrorString	str 'Could not load.  Error was $'	ENDP	END